"""Friendly companion presence with real request states and opt-in preferences."""
BUDDY_CSS = r"""
.friday-buddy{display:grid;grid-template-columns:108px minmax(0,1fr);gap:24px;align-items:center;padding:26px;border:1px solid var(--line);border-radius:24px;background:linear-gradient(120deg,var(--panel),var(--panel2));margin:0 0 20px}.friday-buddy h2{font-size:25px;letter-spacing:-.035em;margin:0 0 8px}.friday-buddy p{font-size:14px;line-height:1.6;color:var(--muted);margin:6px 0}.buddy-core{position:relative;width:100px;height:100px;display:grid;place-items:center;isolation:isolate}.buddy-core:before,.buddy-core:after{content:'';position:absolute;inset:3px;border:1px solid #b5b4f6;border-radius:44% 56% 54% 46%;animation:buddy-orbit 18s linear infinite}.buddy-core:after{inset:13px;border-color:#e9b8aa;animation-direction:reverse;animation-duration:25s}.buddy-core span{width:62px;height:62px;display:grid;place-items:center;border-radius:24px;background:linear-gradient(140deg,#bcb9fb,#f2c9bb);color:#25243d;font-weight:850;font-size:25px;box-shadow:0 9px 28px #aaa1ea30}.friday-buddy[data-state=working] .buddy-core:before{animation-duration:3s;border-color:#7c79e2}.friday-buddy[data-state=error] .buddy-core span{background:#f7c7bf}.buddy-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:15px}.buddy-actions button{min-height:42px;border-radius:13px;padding:10px 14px;border:1px solid var(--line);background:var(--panel);color:var(--ink);font:inherit;font-size:13px;cursor:pointer}.buddy-actions button:hover{border-color:#9b9be5;transform:translateY(-1px)}.buddy-ai-status{font-size:12px!important}.buddy-evidence{font-size:12px;line-height:1.7;margin-top:12px;color:var(--muted)}.buddy-evidence summary{cursor:pointer;min-height:35px}.buddy-profile{border:1px solid var(--line);border-radius:20px;padding:22px;background:var(--panel);margin-bottom:24px}.buddy-profile h2{margin:0 0 8px;font-size:22px}.buddy-profile p{font-size:13px;line-height:1.6;color:var(--muted)}.buddy-profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.buddy-profile label{display:grid;gap:7px;font-size:13px}.buddy-profile input[type=text],.buddy-profile select{width:100%;min-height:44px;border-radius:12px;padding:10px;border:1px solid var(--line);background:var(--panel2);color:var(--ink);font:inherit}.buddy-profile label.buddy-consent{display:flex;align-items:flex-start;gap:10px;line-height:1.6}.buddy-profile button:focus-visible,.buddy-actions button:focus-visible{outline:3px solid #8d86ed;outline-offset:3px}@keyframes buddy-orbit{to{transform:rotate(360deg)}}@media(max-width:650px){.friday-buddy{grid-template-columns:1fr;padding:20px;gap:12px}.buddy-core{width:76px;height:76px}.buddy-core span{width:48px;height:48px;font-size:21px}.buddy-profile-grid{grid-template-columns:1fr}.friday-buddy h2{font-size:22px}}@media(prefers-reduced-motion:reduce){.buddy-core:before,.buddy-core:after{animation:none}.buddy-actions button:hover{transform:none}}html[data-motion=reduced] .buddy-core:before,html[data-motion=reduced] .buddy-core:after{animation:none}
"""

BUDDY_CSS += r'''html[data-motion=off] .buddy-core:before,html[data-motion=off] .buddy-core:after{animation:none}'''

BUDDY_JS = r"""
    {
      const buddy=element('section',null,'friday-buddy');buddy.setAttribute('aria-label','Your Friday financial buddy');buddy.dataset.state='idle';
      const visual=element('div',null,'buddy-core');visual.setAttribute('aria-hidden','true');visual.append(element('span','F'));
      const copy=element('div');const greeting=element('h2','Your money admin. A little less alone.');const intro=element('p','I’m Friday. Keep the records you choose, understand what they mean, and prepare the next safe step.');
      const status=element('p','Checking your saved workspace…','buddy-ai-status');status.setAttribute('role','status');
      const latest=element('details',null,'buddy-evidence');latest.append(element('summary','What AI actually did'));const evidence=element('p','No model call has been made by this overview.');latest.append(evidence);
      const actions=element('div',null,'buddy-actions');const brief=element('button','Friday, brief me');brief.type='button';const personalise=element('button','Make Friday yours');personalise.type='button';const records=element('button','My financial records');records.type='button';actions.append(brief,records,personalise);
      copy.append(greeting,intro,status,actions,latest);buddy.append(visual,copy);everydayMain.prepend(buddy);
      const panel=element('section',null,'buddy-profile');panel.setAttribute('aria-label','Friday communication preferences');panel.append(element('h2','Make Friday yours'),element('p','An optional nickname and explanation style. These preferences never change payment rules. Your nickname stays out of Gemini prompts.'));
      const form=element('form');const grid=element('div',null,'buddy-profile-grid');const nickname=element('input');nickname.type='text';nickname.maxLength=40;nickname.autocomplete='off';nickname.placeholder='Optional nickname';
      const style=element('select');[['CONCISE','Short and clear'],['STEP_BY_STEP','Explain step by step']].forEach(([value,text])=>{const o=element('option',text);o.value=value;style.append(o);});
      const focus=element('select');[['BILLS','Keep bills organised'],['UNDERSTAND_SPENDING','Understand my spending'],['CHECK_REQUESTS','Check unfamiliar requests']].forEach(([value,text])=>{const o=element('option',text);o.value=value;focus.append(o);});
      [['What should Friday call you?',nickname],['How should Friday explain?',style],['What matters most?',focus]].forEach(([name,input])=>{const label=element('label',name);label.append(input);grid.append(label);});
      const useStyle=element('input');useStyle.type='checkbox';useStyle.id='buddy-use-style';const consent=element('label',null,'buddy-consent');consent.append(useStyle,element('span','Use these style and focus choices in future Gemini replies. This does not share my saved financial records or permit payments.'));
      const save=element('button','Save buddy preferences','planner');save.type='submit';const reset=element('button','Forget these preferences','planner');reset.type='button';const feedback=element('p');feedback.setAttribute('role','status');form.append(grid,consent,save,reset,feedback);panel.append(form);settings.prepend(panel);
      let loaded=false,loading=false,requestSerial=0;save.disabled=true;reset.disabled=true;
      function applyPreferences(p){nickname.value=p.display_name;style.value=p.explanation_style;focus.value=p.focus;useStyle.checked=p.share_style_with_ai;greeting.textContent=p.display_name?'Hi '+p.display_name+'. Friday’s here.':'Your money admin. A little less alone.';}
      async function refreshBuddy(){if(loading)return;loading=true;try{const data=await jsonRequest('/api/friday/buddy');if(data.scope!=='FINANCIAL_BUDDY_OVERVIEW'||data.ai_called!==false||data.money_moved!==false||data.payment_authorized!==false)throw new Error('Unexpected buddy authority');if(!loaded){applyPreferences(data.preferences);loaded=true;save.disabled=false;reset.disabled=false;}intro.textContent=data.documents_checked+' saved claim(s) checked · '+data.attention_count+' obligation(s) need a next step · '+data.recorded_artificial_count+' recorded artificial outcome(s). No real bank connected.';status.textContent=data.ai.status==='ON_REQUEST'?'Gemini configured · replies when you ask. Not monitoring your bank.':'Live Gemini is not configured here. Saved records remain available.';if(data.next_item){const next=element('p',(data.next_item.supplier||'Saved obligation')+': '+data.next_item.next_step);latest.querySelector('[data-next-item]')?.remove();next.dataset.nextItem='true';latest.append(next);}}catch{status.textContent='Your workspace is unavailable. No AI check or payment is assumed.';if(!loaded)feedback.textContent='Could not load your preferences. Retry before saving.';}finally{loading=false;}}
      async function saveProfile(p){save.disabled=true;reset.disabled=true;try{const data=await jsonRequest('/api/friday/buddy/preferences','PUT',p);if(data.scope!=='COMMUNICATION_ONLY'||data.financial_rules_changed!==false)throw new Error('Unexpected authority');applyPreferences(data.preferences);document.dispatchEvent(new CustomEvent('friday:preferences-changed'));feedback.textContent='Saved privately. Financial rules are unchanged.';}catch{feedback.textContent='Could not save. Existing preferences and financial rules are unchanged.';}finally{save.disabled=!loaded;reset.disabled=!loaded;}}
      form.addEventListener('submit',event=>{event.preventDefault();if(loaded)saveProfile({display_name:nickname.value,explanation_style:style.value,focus:focus.value,share_style_with_ai:useStyle.checked});});
      reset.addEventListener('click',()=>{if(loaded&&confirm('Forget your nickname and communication preferences? Financial records and payment rules will remain.'))saveProfile({display_name:'',explanation_style:'CONCISE',focus:'BILLS',share_style_with_ai:false});});
      personalise.addEventListener('click',()=>{show('settings');panel.scrollIntoView({block:'start'});nickname.focus();});records.addEventListener('click',()=>show('review'));
      brief.addEventListener('click',()=>{show('home');const checkbox=$('friday-chat-workspace');if(!checkbox.checked){checkbox.focus();toast('Choose Include my saved inbox first. Friday needs your permission to summarise your records.');return;}$('home-command').value='Give me a short briefing of the saved records I shared: what needs attention, what remains uncertain, and the one useful next step. Do not claim bank settlement or completed actions.';$('home-command').focus();toast('Briefing request ready. Choose Ask Friday to send the selected context.');});
      const requestBeforeBuddy=jsonRequest;
      const buddyModelPaths=['/api/friday/chat','/api/friday/tasks','/api/friday/reviews','/api/friday/diary/prepare'];
      jsonRequest=async function(path,method='GET',body){const aiRequest=method==='POST'&&buddyModelPaths.includes(path);const serial=aiRequest?++requestSerial:0;if(aiRequest){buddy.dataset.state='working';status.textContent='Friday is working on your request. No completed financial outcome is assumed.';}try{const result=await requestBeforeBuddy(path,method,body);if(aiRequest&&serial===requestSerial){const provenance=result.document?.provenance||result.provenance||result;const calls=provenance.model_calls||0;buddy.dataset.state='idle';status.textContent=calls?'AI response received. Review the answer or checked next step.':'Request returned without a reported model call.';evidence.textContent=(provenance.mode||'Mode not reported')+' · '+(provenance.model||'Model not reported')+' · '+calls+' model call(s). '+(result.payment_authorized===false?'No payment authorised.':'Preparation is not execution.');}return result;}catch(error){if(aiRequest&&serial===requestSerial){buddy.dataset.state='error';status.textContent='The request failed or is unavailable. No success is assumed.';evidence.textContent='No validated AI result received for this request.';}throw error;}};
      const showBeforeBuddy=show;show=function(name,push=true){showBeforeBuddy(name,push);if(name==='home'||name==='settings')refreshBuddy();};
      refreshBuddy();
      document.addEventListener('friday:followup-changed',refreshBuddy);
    }
"""
